import IO
import Proc
import FS
import Path
import List
import Map
import Hash
import Digest
import String

let add m p =
  let h = Digest.hex (Hash.file! Digest.Sha256 p);
  Map.set h (p :: (Map.get h m |> Option.default [])) m

let main dir =
  let root = Path.of_string dir;
  let files = FS.glob_in **/* root |> List.filter_map (Path.relative_to root);
  let strs = List.map Path.to_string files;
  let m = List.fold_left (fn acc s -> add_rel root acc s) Map.empty strs;
  let groups = Map.values m |> List.map List.sort |> List.filter (fn g -> List.length g > 1) |> List.sort_by (fn g -> List.head! g);
  IO.print (String.join "\n" (List.map (fn g -> String.join "\n" g ++ "\n") groups))

let add_rel root m s =
  let h = Digest.hex (Hash.file! Digest.Sha256 (Path.join root (Path.of_string s)));
  Map.set h (s :: (Map.get h m |> Option.default [])) m

match Proc.args () with
| [] ->
  IO.println_err "usage: prog DIR"
  Proc.exit 2
| d :: _ ->
  if FS.dir? (Path.of_string d) then main d else
    (IO.println_err "not a directory"; Proc.exit 1)
EOF
