import IO
import String
import List
import Map

let first sep s = List.head! (String.split sep s)

let host_of line =
  let rest =
    if String.starts_with? "http://" line then Some (String.slice 7 (String.length line) line)
    else if String.starts_with? "https://" line then Some (String.slice 8 (String.length line) line)
    else None
  match rest with
  | None -> None
  | Some r ->
    let h = String.lower (first ":" (first "#" (first "?" (first "/" r))))
    if String.empty? h then None else Some h

let lines = String.lines (IO.read_all! ()) |> List.map String.trim |> List.filter (fn l -> !(String.empty? l))
let hosts = List.map host_of lines
let good = List.filter_map (fn h -> h) hosts
let bad = List.length hosts - List.length good
let ranked = List.sort_by (fn (h, c) -> (0 - c, h)) (Map.to_list (List.tally good))
List.each (fn (h, c) -> IO.println "%{c} %{h}") ranked
if bad > 0 then IO.println "%{bad} invalid" else ()
EOF
