import IO
import Stream
import Decode
import Map
import List
import String

let rec_dec = Decode.map2 (fn e m -> (e, m)) (Decode.field "endpoint" Decode.string) (Decode.field "ms" Decode.int)

let pct sorted n p =
  let r = (p * n + 99) / 100;
  List.get! (r - 1) sorted

let step acc line =
  let {groups, skipped} = acc;
  if String.empty? (String.trim line) then acc
  else
    match Decode.run rec_dec line with
    | Ok (e, m) ->
      if m < 0 then {groups, skipped = skipped + 1}
      else {groups = Map.update e [] (fn xs -> m :: xs) groups, skipped}
    | Error _ -> {groups, skipped = skipped + 1}

let {groups, skipped} = IO.stdin_lines () |> Stream.fold_left step {groups = Map.empty, skipped = 0}
List.each (fn k ->
  let sorted = List.sort (Option.get! (Map.get k groups));
  let n = List.length sorted;
  IO.println "%{k} count=%{n} p50=%{pct sorted n 50} p95=%{pct sorted n 95}") (List.sort (Map.keys groups))
if skipped > 0 then IO.println "skipped %{skipped}" else ()
EOF
