import IO
import List
import Map
import String
import Decode
import Stream

let dec = Decode.map2 (fn e m -> (e, m)) (Decode.field "endpoint" Decode.string) (Decode.field "ms" Decode.int)

let parse line =
  match Decode.run dec line with
  | Ok (e, m) -> if m >= 0 then Some (e, m) else None
  | Error _ -> None

let pct vs p =
  let n = List.length vs;
  let r = (p * n + 99) / 100;
  List.get! (r - 1) vs

let step (groups, skipped) line =
  if String.empty? (String.trim line) then (groups, skipped)
  else
    match parse line with
    | Some (e, m) -> (Map.update e (fn o -> match o with | Some l -> Some (m :: l) | None -> Some [m]) groups, skipped)
    | None -> (groups, skipped + 1)

let (groups, skipped) = IO.stdin_lines () |> Stream.fold_left step (Map.empty, 0)

let _ = List.each (fn (e, l) ->
  let vs = List.sort l;
  IO.println "%{e} count=%{List.length vs} p50=%{pct vs 50} p95=%{pct vs 95}") (List.sort_by (fn (e, _) -> e) (Map.to_list groups))

let _ = if skipped > 0 then IO.println "skipped %{skipped}" else ()
EOF
